const now = new Date().toISOString();

// Helper to generate a card easily
function createCardItem(
  id: string,
  deckId: string,
  question: string,
  answer: string,
  tags: string[],
  state: Card['state'] = 'new',
  dueOffsetDays: number = 0,
  interval: number = 0,
  favorite: boolean = false
): Card {
  const due = new Date();
  due.setDate(due.getDate() + dueOffsetDays);

  return {
    id,
    deckId,
    question,
    answer,
    tags,
    createdAt: now,
    updatedAt: now,
    dueDate: due.toISOString(),
    lastReviewedAt: dueOffsetDays < 0 ? new Date(due.getTime() - 86400000).toISOString() : null,
    interval,
    ease: 2.5,
    repetitions: state === 'new' ? 0 : 2,
    lapses: 0,
    difficulty: 5,
    stability: 2.0,
    state,
    favorite,
    flagged: false,
  };
}

